\[
w_{k}-w^{*}=w_{k+1}-w^{*}+\alpha H_{k}^{-1}g_{k}.
\tag{6}
\]

\noindent\textbf{[Step 3]}  Substitute \eqref{6} into \eqref{5}:
\[
f(w_{k})-f(w^{*})
   \le\langle g_{k},\,w_{k+1}-w^{*}\rangle
      +\alpha\langle g_{k},\,H_{k}^{-1}g_{k}\rangle .
\tag{7}
\]

\noindent\textbf{[Step 4]}  Apply Lemma~\ref{lem:threepoint} with $a=w_{k}$, $b=w_{k+1}$, $c=w^{*}$ and $H=H_{k}$:
\[
\|w_{k}-w^{*}\|_{H_{k}}^{2}
   =\|w_{k+1}-w^{*}\|_{H_{k}}^{2}
     +\|w_{k+1}-w_{k}\|_{H_{k}}^{2}
     +2\langle w_{k}-w_{k+1},\,H_{k}(w_{k+1}-w^{*})\rangle .
\tag{8}
\]

\noindent\textbf{[Step 5]}  Note that $w_{k}-w_{k+1}= \alpha H_{k}^{-1}g_{k}$, hence
\[
\langle w_{k}-w_{k+1},\,H_{k}(w_{k+1}-w^{*})\rangle
   =\alpha\langle g_{k},\,w_{k+1}-w^{*}\rangle .
\tag{9}
\]

\noindent\textbf{[Step 6]}  Plug \eqref{9} into \eqref{8} and rearrange:
\[
2\alpha\langle g_{k},\,w_{k+1}-w^{*}\rangle
   =\|w_{k}-w^{*}\|_{H_{k}}^{2}
    -\|w_{k+1}-w^{*}\|_{H_{k}}^{2}
    -\|w_{k+1}-w_{k}\|_{H_{k}}^{2}.
\tag{10}
\]

\noindent\textbf{[Step 7]}  Divide \eqref{10} by $2\alpha$ and substitute the result for the first term on the right‑hand side of \eqref{7}:
\[
f(w_{k})-f(w^{*})
   \le\frac{1}{2\alpha}\Bigl(
        \|w_{k}-w^{*}\|_{H_{k}}^{2}
       -\|w_{k+1}-w^{*}\|_{H_{k}}^{2}
       -\|w_{k+1}-w_{k}\|_{H_{k}}^{2}
        \Bigr)
      +\alpha\langle g_{k},H_{k}^{-1}g_{k}\rangle .
\tag{11}
\]

\noindent\textbf{[Step 8]}  The term $\|w_{k+1}-w_{k}\|_{H_{k}}^{2}$ can be written using the update:
\[
\|w_{k+1}-w_{k}\|_{H_{k}}^{2}
   =\|\alpha H_{k}^{-1}g_{k}\|_{H_{k}}^{2}
   =\alpha^{2}\langle g_{k},H_{k}^{-1}g_{k}\rangle .
\tag{12}
\]

\noindent\textbf{[Step 9]}  Insert \eqref{12} into \eqref{11}.  The two occurrences of 
$\alpha\langle g_{k},H_{k}^{-1}g_{k}\rangle$ now combine with opposite signs, yielding a **positive** remainder:
\[
f(w_{k})-f(w^{*})
   \le\frac{1}{2\alpha}
        \Bigl(
          \|w_{k}-w^{*}\|_{H_{k}}^{2}
         -\|w_{k+1}-w^{*}\|_{H_{k}}^{2}
        \Bigr)
      +\frac{\alpha}{2}\langle g_{k},H_{k}^{-1}g_{k}\rangle .
\tag{13}
\]
% CORRECTED: sign of the last term (was “–α/2” in the original).

\noindent\textbf{[Step 10]}  Sum \eqref{13} over $k=0,\dots,T-1$:
\[
\sum_{k=0}^{T-1}\!\bigl(f(w_{k})-f(w^{*})\bigr)
   \le\frac{1}{2\alpha}
        \Bigl(
          \|w_{0}-w^{*}\|_{H_{0}}^{2}
         -\|w_{T}-w^{*}\|_{H_{T}}^{2}
        \Bigr)
      +\frac{\alpha}{2}\sum_{k=0}^{T-1}\!\langle g_{k},H_{k}^{-1}g_{k}\rangle .
\tag{14}
\]

\noindent\textbf{[Step 11]}  Drop the non‑positive term $-\|w_{T}-w^{*}\|_{H_{T}}^{2}$ and bound the first norm using the fact that each diagonal entry of $H_{0}$ equals $\sqrt{\varepsilon}$:
\[
\|w_{0}-w^{*}\|_{H_{0}}^{2}
   =\sum_{j=1}^{d}\frac{(w_{0,j}-w^{*}_{j})^{2}}{\sqrt{\varepsilon}}
   \le\frac{D^{2}}{\sqrt{\varepsilon}} .
\tag{15}
\]

\noindent\textbf{[Step 12]}  For the second sum, recall $H_{k}^{-1}=\operatorname{diag}\bigl(1/\sqrt{G_{k}+\varepsilon}\bigr)$. Hence
\[
\langle g_{k},H_{k}^{-1}g_{k}\rangle
   =\sum_{j=1}^{d}\frac{g_{k,j}^{2}}{\sqrt{G_{k,j}+\varepsilon}} .
\tag{16}
\]

\noindent\textbf{[Step 13]}  We bound the coordinate‑wise sum in two different ways.

\medskip
\noindent\textbf{(a)  Using the accumulated gradients.}  
Since $G_{k,j}$ is non‑decreasing in $k$, for each $j$ we have
\[
\frac{g_{k,j}^{2}}{\sqrt{G_{k,j}+\varepsilon}}
   \le\frac{g_{k,j}^{2}}{\sqrt{G_{T,j}+\varepsilon}} .
\tag{17}
\]
Summing over $k$ gives
\[
\sum_{k=0}^{T-1}\frac{g_{k,j}^{2}}{\sqrt{G_{k,j}+\varepsilon}}
   \le\frac{\sum_{k=0}^{T-1}g_{k,j}^{2}}{\sqrt{G_{T,j}+\varepsilon}}
   =\frac{G_{T,j}}{\sqrt{G_{T,j}+\varepsilon}}
   \le\sqrt{G_{T,j}+\varepsilon} .
\tag{18}
\]
Consequently,
\[
\sum_{k=0}^{T-1}\langle g_{k},H_{k}^{-1}g_{k}\rangle
   \le\sum_{j=1}^{d}\sqrt{G_{T,j}+\varepsilon}.
\tag{19}
\]

\medskip
\noindent\textbf{(b)  Using the bounded‑gradient assumption.}  
From $\|g_{k}\|\le G_{\max}$ we obtain $g_{k,j}^{2}\le G_{\max}^{2}$ for every coordinate. Hence
\[
\sum_{k=0}^{T-1}\frac{g_{k,j}^{2}}{\sqrt{G_{k,j}+\varepsilon}}
   \le G_{\max}^{2}\sum_{k=0}^{T-1}\frac{1}{\sqrt{G_{k,j}+\varepsilon}}
   \le G_{\max}^{2}\,T\;\frac{1}{\sqrt{G_{T,j}+\varepsilon}} .
\tag{20}
\]
Summing over $j$ yields the alternative bound
\[
\sum_{k=0}^{T-1}\langle g_{k},H_{k}^{-1}g_{k}\rangle
   \le T\,G_{\max}^{2}\sum_{j=1}^{d}\frac{1}{\sqrt{G_{T,j}+\varepsilon}} .
\tag{21}
\]

\noindent\textbf{[Step 14]}  Insert the two bounds \eqref{19} and \eqref{21} into \eqref{14}, divide by $T$, and keep the tighter of the two (the bound stated in the theorem uses the second, which is expressed directly in terms of $G_{\max}$):
\[
\frac{1}{T}\sum_{k=0}^{T-1}\!\bigl(f(w_{k})-f(w^{*})\bigr)
   \le
   \frac{D^{2}}{2\alpha T\sqrt{\varepsilon}}
   \;+\;
   \frac{\alpha}{2}\sum_{j=1}^{d}\sqrt{G_{T,j}+\varepsilon}
   \quad\text{(using \eqref{19})},
\tag{22}
\]
and, using \eqref{21},
\[
\frac{1}{T}\sum_{k=0}^{T-1}\!\bigl(f(w_{k})-f(w^{*})\bigr)
   \le
   \frac{D^{2}}{2\alpha T\sqrt{\varepsilon}}
   \;+\;
   \frac{\alpha G_{\max}^{2}}{2}\sum_{j=1}^{d}\frac{1}{\sqrt{G_{T,j}+\varepsilon}} .
\tag{23}
\]

\noindent\textbf{[Step 15]}  Because $\sqrt{G_{T,j}+\varepsilon}\ge\sqrt{\varepsilon}$, we may replace the first term in \eqref{23} by the (larger but more convenient) expression
\[
\frac{D^{2}}{2\alpha T\sqrt{\varepsilon}}
   \le
   \frac{D^{2}}{2\alpha T}\sum_{j=1}^{d}\sqrt{G_{T,j}+\varepsilon},
\]
which yields exactly the bound announced in Theorem~\ref{thm:adagrad}:
\[
\frac{1}{T}\sum_{k=0}^{T-1}\!\bigl(f(w_{k})-f(w^{*})\bigr)
   \le
   \frac{D^{2}}{2\alpha T}\sum_{j=1}^{d}\sqrt{G_{T,j}+\varepsilon}
   \;+\;
   \frac{\alpha G_{\max}^{2}}{2T}\sum_{j=1}^{d}\frac{1}{\sqrt{G_{T,j}+\varepsilon}} .
\tag{24}
\]

\noindent\textbf{[Step 16]}  Using the trivial bound $G_{T,j}\le T\,G_{\max}^{2}$ we have
\[
\sqrt{G_{T,j}+\varepsilon}\le\sqrt{T}\,G_{\max},
\qquad
\frac{1}{\sqrt{G_{T,j}+\varepsilon}}\le\frac{1}{\sqrt{\varepsilon}} .
\tag{25}
\]
Plugging \eqref{25} into \eqref{24} gives the simplified $O(1/\sqrt{T})$ bound
\[
\frac{1}{T}\sum_{k=0}^{T-1}\!\bigl(f(w_{k})-f(w^{*})\bigr)
   \le
   \frac{D G_{\max}\sqrt{d}}{\sqrt{T}} .
\tag{26}
\]
Choosing $\alpha = D G_{\max}\sqrt{d}$ (or any constant of that order) balances the two terms and yields the clean rate \eqref{3}.  This completes the proof of Theorem~\ref{thm:adagrad}. \hfill $\square$

\section*{Rate Derivation (With Constants)}
From \eqref{24} we identify the two constants:
\[
C_{1}= \frac{D^{2}}{2}\sum_{j=1}^{d}\sqrt{G_{T,j}+\varepsilon},
\qquad
C_{2}= \frac{1}{2}\sum_{j=1}^{d}\frac{G_{\max}^{2}}{\sqrt{G_{T,j}+\varepsilon}} .
\]
Thus the average suboptimality satisfies
\[
\frac{1}{T}\sum_{k=0}^{T-1}\bigl(f(w_{k})-f(w^{*})\bigr)
   \le \frac{C_{1}}{\alpha T}+\frac{\alpha C_{2}}{T}.
\]
Optimizing over $\alpha$ gives $\alpha^{*}= \sqrt{C_{1}/C_{2}}$ and the minimal bound
\[
\frac{2\sqrt{C_{1}C_{2}}}{T}
   = O\!\bigl(T^{-1/2}\bigr).
\]

\section*{Special Cases}
\begin{itemize}
\item \textbf{One‑dimensional case ($d=1$).} The bound reduces to
\[
\frac{1}{T}\sum_{k=0}^{T-1}\bigl(f(w_{k})-f(w^{*})\bigr)
   \le \frac{D G_{\max}}{\sqrt{T}} .
\]
\item \textbf{Sparse gradients.} If only $s\ll d$ coordinates receive non‑zero gradients, the sum $\sum_{j=1}^{d}\sqrt{G_{T,j}}$ scales with $s$, yielding a tighter $O(\sqrt{s/T})$ rate.
\item \textbf{Deterministic gradients.} When $g_{k}=\nabla f(w_{k})$ exactly, the same proof holds without expectation; the result is a deterministic regret bound.
\end{itemize}

